css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .74); height: calc(var(--loader-size) * .88); position: relative; overflow: hidden; border-radius: 46% 46% 40% 40%; background: repeating-radial-gradient(circle at 50% 64%, transparent 0 6.5%, var(--accent-2) 6.5% 9%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 14%, var(--accent-2)); }
.loader::after { content: ''; position: absolute; inset: 0; background: var(--accent); animation: verify calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader span { position: absolute; z-index: 2; left: 0; width: 100%; height: 9%; background: linear-gradient(transparent, var(--accent), transparent); box-shadow: 0 0 calc(var(--loader-size) * .09) var(--accent); animation: fscan calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
@keyframes fscan { 0% { top: -9%; } 50% { top: 100%; } 100% { top: -9%; } }
@keyframes verify { 0%, 42% { opacity: 0; } 52% { opacity: .3; } 68%, 100% { opacity: 0; } }
